import{_ as r,a0 as o,w as p,s as g,I as l,x as e,a1 as a,A as s,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Linux 系統實時監控的瑞士軍刀 —— Glances | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系統實時監控的瑞士軍刀 —— Glances | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系統實時監控的瑞士軍刀 —— Glances | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系統實時監控的瑞士軍刀 —— Glances | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Glances – An Advanced Real Time System Monitoring Tool for Linux","title":"Linux 系統實時監控的瑞士軍刀 —— Glances","tag":"201403","desc":""},"relativePath":"201403/Glances – An Advanced Real Time System Monitoring Tool for Linux.md","filePath":"[post].md"}'),d={name:"201403/Glances – An Advanced Real Time System Monitoring Tool for Linux.md"};function u(c,n,m,x,f,G){const t=o("Link");return p(),g("div",null,[n[25]||(n[25]=l("h1",{id:"linux-系統實時監控的瑞士軍刀-——-glances",tabindex:"-1"},[e("Linux 系統實時監控的瑞士軍刀 —— Glances "),l("a",{class:"header-anchor",href:"#linux-系統實時監控的瑞士軍刀-——-glances","aria-label":"Permalink to “Linux 系統實時監控的瑞士軍刀 —— Glances”"},"​")],-1)),l("p",null,[n[1]||(n[1]=e("早些時候，我們提到過有很多可以用來監視系統性能的 Linux ",-1)),a(t,{href:"http://www.tecmint.com/command-line-tools-to-monitor-linux-performance/"},{default:s(()=>[...n[0]||(n[0]=[e("系統監視工具",-1)])]),_:1}),n[2]||(n[2]=e("。 但我們估計，或許更多的用户會傾向與絕大多數 Linux 發行版都帶的工具 （",-1)),n[3]||(n[3]=l("strong",null,"top",-1)),n[4]||(n[4]=e(" 命令）。",-1))]),l("p",null,[a(t,{href:"http://www.tecmint.com/12-top-command-examples-in-linux/"},{default:s(()=>[...n[5]||(n[5]=[e("top 命令",-1)])]),_:1}),n[6]||(n[6]=e("是 Linux 下的一個實時任務管理器， 同時也是用於在 ",-1)),n[7]||(n[7]=l("strong",null,"GNU/Linux",-1)),n[8]||(n[8]=e(" 發行版中尋找系統性能方面的瓶頸，並幫助我們作出正確操作的常用系統監視工具。 她有着一個極為簡潔的界面，並自帶少量的可以幫助我們快速瞭解系統性能的實用選項。",-1))]),n[26]||(n[26]=i('<p>但是，有些時候想要通過她尋找一個佔用系統資源比較大的應用或進程可能會比較困難。 因為 top 命令本身並不會幫助我們高亮那些吃太多 <strong>CPU</strong>，<strong>內存</strong>，或者其他資源的程序。</p><p>為了達到這個目標，這裏我們將介紹一款超牛逼的系統監視程序 —— <strong>Glances</strong>。 她可以自動高亮利用最高系統資源的程序，併為 Linux/Unix 服務器提供儘可能多的信息。</p><h3 id="什麼是-glances" tabindex="-1">什麼是 Glances？ <a class="header-anchor" href="#什麼是-glances" aria-label="Permalink to “什麼是 Glances？”">​</a></h3><p><strong>Glances</strong> 是一個由 Python 編寫，使用 <strong>psutil</strong> 庫來從系統抓取信息的基於 curses 開發的跨平台命令列系統監視工具。 通過 Glances，我們可以監視 <strong>CPU，平均負載，內存，網絡流量，磁盤 I/O，其他處理器</strong> 和 <strong>文件系統</strong> 空間的利用情況。</p><p>Glances 是一個用來監視 <strong>GNU/Linux</strong> 和 <strong>FreeBSD</strong> 操作系統的 <strong>GPL</strong> 授權的自由軟件。</p><p>Glances 同時也提供了很多實用的選項。 其中我們能夠在配置文件見到的一項主要的功能就是設置關鍵值及相應的標籤 （<strong>careful[小心]</strong>, <strong>warning[警告]</strong> 和 <strong>critical[嚴重]</strong>）， 然後她會自動幫我們用不同顏色標出系統達到某個瓶頸的信息。</p><h3 id="glances-主要功能" tabindex="-1">Glances 主要功能 <a class="header-anchor" href="#glances-主要功能" aria-label="Permalink to “Glances 主要功能”">​</a></h3><ul><li>CPU 信息 （用户的相關應用, 系統核心程序和空閒程序）</li><li>總內存信息，包括了物理內存，交換空間和空閒內存等等</li><li>之前的 1 分鐘、5 分鐘和 15 分鐘平均的 CPU 負載</li><li>網絡鏈接的下行和上行速度</li><li>處理器總數，以及其活動狀態</li><li>硬盤 I/O 相關（讀寫）速度詳情</li><li>當前掛載設備的磁盤使用情況</li><li>高 CPU 和內存使用的進程名，和相關應用的位置</li><li>在底部顯示當前日期和時間</li><li>將消耗最高系統資源的進程用紅色標出</li></ul><p>下面是一個 Glances 的使用截圖：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Glances-Monitoring.jpeg" alt="Glances View"></p><h3 id="在-linux-unix-系統中安裝-glances" tabindex="-1">在 Linux/Unix 系統中安裝 Glances <a class="header-anchor" href="#在-linux-unix-系統中安裝-glances" aria-label="Permalink to “在 Linux/Unix 系統中安裝 Glances”">​</a></h3>',11)),l("p",null,[n[10]||(n[10]=e("雖然這個工具的發佈比較晚，但你仍然可以在 ",-1)),n[11]||(n[11]=l("strong",null,"Red Hat",-1)),n[12]||(n[12]=e(" 系的系統中通過 ",-1)),a(t,{href:"http://www.tecmint.com/how-to-enable-epel-repository-for-rhel-centos-6-5/"},{default:s(()=>[...n[9]||(n[9]=[e("EPEL 軟件源",-1)])]),_:1}),n[13]||(n[13]=e("安裝。在終端用下面的命令安裝：",-1))]),n[27]||(n[27]=i(`<h4 id="對於-rhel-centos-fedora-發行版" tabindex="-1">對於 RHEL/CentOS/Fedora 發行版 <a class="header-anchor" href="#對於-rhel-centos-fedora-發行版" aria-label="Permalink to “對於 RHEL/CentOS/Fedora 發行版”">​</a></h4><pre><code># yum install -y glances
</code></pre><h4 id="對於-debian-ubuntu-linux-mint-發行版" tabindex="-1">對於 Debian/Ubuntu/Linux Mint 發行版 <a class="header-anchor" href="#對於-debian-ubuntu-linux-mint-發行版" aria-label="Permalink to “對於 Debian/Ubuntu/Linux Mint 發行版”">​</a></h4><pre><code>$ sudo apt-add-repository ppa:arnaud-hartmann/glances-stable
$ sudo apt-get update
$ sudo apt-get install glances
</code></pre><h3 id="如何使用-glances" tabindex="-1">如何使用 Glances <a class="header-anchor" href="#如何使用-glances" aria-label="Permalink to “如何使用 Glances”">​</a></h3><p>首先，你需要在終端中輸入以下命令</p><pre><code># glances
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Glances-Screen.jpeg" alt="Glances Preview – Ubuntu 13.10"></p><p>按下 ‘<strong>q</strong>‘ （‘<strong>ESC</strong>‘ 和 ‘<strong>Ctrl-C</strong>‘ 也可以） 退出 Glances 終端。 這裏是從 <strong>CentOS 6.5</strong> 截取的另一張截圖：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Glances-Screen-Centos.jpeg" alt="Glances Preview – CentOS 6.5"></p><p>Glances 的默認刷新頻率是 <strong>1</strong> （秒），但是你可以通過在終端指定參數來手動定義其刷新頻率</p><pre><code># glances -t 2
</code></pre><h3 id="glances-中顏色的含義" tabindex="-1">Glances 中顏色的含義 <a class="header-anchor" href="#glances-中顏色的含義" aria-label="Permalink to “Glances 中顏色的含義”">​</a></h3><p>Glances 會用一下幾種顏色來代表狀態：</p><ul><li>綠色：OK（一切正常）</li><li>藍色：CAREFUL（需要注意）</li><li>紫色：WARNING（警告）</li><li>紅色：CRITICAL（嚴重）</li></ul><p>閥值可以在配置文件中設置，一般閥值被默認設置為（<strong>careful=50</strong>、<strong>warning=70</strong>、<strong>critical=90</strong>）。</p><p>我們可以按照自己的需求在配置文件（默認在 <strong>/etc/glances/glances.conf</strong>）中自定義。</p><h3 id="glances-的選項" tabindex="-1">Glances 的選項 <a class="header-anchor" href="#glances-的選項" aria-label="Permalink to “Glances 的選項”">​</a></h3><p>除了很多命令列選項之外，Glances 還提供了更多的可在其運行時開關輸出信息選項的<strong>快捷鍵</strong>，下面是一些例子：</p><ul><li>a – 對進程自動排序</li><li>c – 按 CPU 百分比對進程排序</li><li>m – 按內存百分比對進程排序</li><li>p – 按進程名字母順序對進程排序</li><li>i – 按讀寫頻率（I/O）對進程排序</li><li>d – 顯示/隱藏磁盤 I/O 統計信息</li><li>f – 顯示/隱藏文件系統統計信息</li><li>n – 顯示/隱藏網絡接口統計信息</li><li>s – 顯示/隱藏傳感器統計信息</li><li>y – 顯示/隱藏硬盤温度統計信息</li><li>l – 顯示/隱藏日誌（log）</li><li>b – 切換網絡 I/O 單位（Bytes/bits）</li><li>w – 刪除警告日誌</li><li>x – 刪除警告和嚴重日誌</li><li>1 – 切換全局 CPU 使用情況和每個 CPU 的使用情況</li><li>h – 顯示/隱藏這個幫助畫面</li><li>t – 以組合形式瀏覽網絡 I/O</li><li>u – 以累計形式瀏覽網絡 I/O</li><li>q – 退出（‘<strong>ESC</strong>‘ 和 ‘<strong>Ctrl&amp;C</strong>‘ 也可以）</li></ul><h3 id="遠程使用-glances" tabindex="-1">遠程使用 Glances <a class="header-anchor" href="#遠程使用-glances" aria-label="Permalink to “遠程使用 Glances”">​</a></h3><p>你甚至也可以通過 Glances 來監視遠程系統。 要在遠程系統使用 ‘<strong>glances</strong>’，需要在服務器運行 ‘<strong>glances -s</strong>’（-s 啓動服務器/客户端模式）命令。</p><pre><code># glances -s

Define the password for the Glances server
Password: 
Password (confirm): 
Glances server is running on 0.0.0.0:61209
</code></pre><p><strong>注意</strong>：當你執行了‘<strong>glances</strong>’命令後，她會讓你為 Glances 服務器設置密碼。</p><p>當你設置完畢，你將看到 “Glances server is running on 0.0.0.0:61209” （Glances 服務器正在 0.0.0.0 的 61209 端口運行）的消息。</p><p>當 Glances 服務器啓動後，到本地執行下面的命令來指定服務器IP地址或主機名以鏈接。</p><p>注：這裏的 ‘<strong>172.16.27.56</strong>’ 是我 Glances 服務器的 IP 地址。</p><pre><code># glances -c -P 172.16.27.56
</code></pre><p>下面是一些在使用服務器/客户端模式時必須知道的事情：</p><pre><code>* 在服務器模式，你可以通過 \`-B 地址\` 來設置綁定地址，也可以通過 \`-p 端口\` 來綁定監聽的 TCP 端口
* 在客户端模式，你可以通過同樣的 \`-p 端口\` 來指定服務器端口
* 默認的綁定地址是 0.0.0.0，但這麼做會監聽所有網絡接口的指定端口
* 在服務器/客户端模式下，限制的閥值將由服務器的設置決定
* 你也可以在命令列下用過 \`-P 密碼\` 的方式來為服務器端設置一個密碼
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><strong>Glances</strong> 對於大多用户而言是個在系統資源上提供過多信息的工具。但是如果你是一個想要僅從命令列就能快速獲取系統整體狀況的系統管理員，那這個工具絕對是你的必備利器。</p><h3 id="譯者注" tabindex="-1">譯者注 <a class="header-anchor" href="#譯者注" aria-label="Permalink to “譯者注”">​</a></h3><ol><li>請不要將 glances（本文中的工具）和 glance（一個 OpenStack 的工具）這兩個包搞混了</li><li>Ubuntu 官方 Extra 源中的 glances 因為 python 庫移動的問題導致無法正常使用 但可以通過建立軟鏈接的方式臨時修復：sudo ln -s /usr/lib/python2.7/dist-packages/glances /usr/share/pyshared/glances</li></ol><hr>`,35)),l("p",null,[n[15]||(n[15]=e("via: ",-1)),a(t,{href:"http://www.tecmint.com/glances-an-advanced-real-time-system-monitoring-tool-for-linux/"},{default:s(()=>[...n[14]||(n[14]=[e("http://www.tecmint.com/glances-an-advanced-real-time-system-monitoring-tool-for-linux/",-1)])]),_:1})]),l("p",null,[n[18]||(n[18]=e("譯者：",-1)),a(t,{href:"https://github.com/vizv"},{default:s(()=>[...n[16]||(n[16]=[e("VizV",-1)])]),_:1}),n[19]||(n[19]=e(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:s(()=>[...n[17]||(n[17]=[e("wxy",-1)])]),_:1})]),l("p",null,[n[22]||(n[22]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[20]||(n[20]=[e("LCTT",-1)])]),_:1}),n[23]||(n[23]=e(" 原創翻譯，",-1)),a(t,{href:"http://linux.cn/"},{default:s(()=>[...n[21]||(n[21]=[e("Linux中國",-1)])]),_:1}),n[24]||(n[24]=e(" 榮譽推出",-1))])])}const C=r(d,[["render",u]]);export{w as __pageData,C as default};
